<?php
/**
 * Front door of the dynamic site: every URL without a real file comes here
 * (see .htaccess, generated by scripts/build-redirects.py --dynamic).
 *
 * Safety net: until the server is switched on (app/config.local.php with
 * 'enabled' => true, written by scripts/go-live.sh; see GO-LIVE.md), this
 * keeps serving the static site exactly as before: index.html for the home
 * page, 404.html for anything else.
 */

declare(strict_types=1);

require_once __DIR__ . '/app/bootstrap.php';

if (!config('enabled') || !is_file(content_path('site.json'))) {
    $path = path_normalize($_SERVER['REQUEST_URI'] ?? '/') ?? '/';
    if (in_array($path, ['/', '/index.php'], true) && is_file(__DIR__ . '/index.html')) {
        header('Content-Type: text/html; charset=utf-8');
        readfile(__DIR__ . '/index.html');
        exit;
    }
    http_response_code(404);
    header('Content-Type: text/html; charset=utf-8');
    if (is_file(__DIR__ . '/404.html')) {
        readfile(__DIR__ . '/404.html');
    } else {
        echo '<h1>Page not found</h1>';
    }
    exit;
}

front_handle_request();
